<?php
require dirname(__DIR__).'/vendor/autoload.php';use app\services\CatalogLegacyPreview as L;use app\services\CatalogProperties as P;
function normalizationCheck($ok,$message){if(!$ok)throw new RuntimeException($message);}
$p=['id'=>1,'sku'=>'TEST','name'=>'6.50-10 Шина пневматическая','category_id'=>18];$attrs=[];foreach([4=>'6.50-10',12=>'7',72=>'9.2',69=>'80',73=>'25',74=>'рулевая',7=>'10 дюймов',65=>'4 1/2',62=>'грунт, песок'] as$id=>$raw)$attrs[]=['attribute_id'=>$id,'attribute_text'=>$raw];
$r=L::forProduct($p,$attrs);normalizationCheck($r['proposed']['type']==='tyre_pneumatic'&&!$r['unmapped'],'Explicit name and literal fields recognised');$v=$r['proposed']['values'];normalizationCheck($v['legacy_max_pressure_psi']['value']==='7'&&$v['legacy_max_pressure_kgf_cm2']['value']==='9.2'&&!isset($v['inflation_pressure_kpa']),'No pressure conversion or relabelling');normalizationCheck($v['section_height_mm']['value']==='80'&&!isset($v['aspect_ratio_pct']),'Height mm is not aspect ratio');normalizationCheck($v['manufacturer_max_speed_kmh']['value']==='25'&&!$r['proposed']['ratings'],'Numeric speed is not a service index');normalizationCheck($v['section_width_in']['value']==='4.5'&&$v['rim_diameter_in']['value']==='10','Exact fraction and same-unit suffix');normalizationCheck(str_contains($v['section_width_in']['source_ref'],'4 1/2'),'Raw fraction preserved as source');normalizationCheck($v['tire_type']['verification']==='legacy_unverified'&&str_contains($v['tire_type']['source_ref'],'product.name'),'Name evidence never auto-confirmed');P::normalize($r['proposed']);
$rim=L::forProduct(array_replace($p,['category_id'=>26,'name'=>'Диск']),[['attribute_id'=>16,'attribute_text'=>'Диск сборный']]);normalizationCheck($rim['proposed']['values']['rim_construction']['value']===['split']&&!isset($rim['proposed']['values']['sealing'])&&!$rim['unmapped'],'Rim construction is not tyre sealing');
$conflict=L::forProduct($p,[['attribute_id'=>61,'attribute_text'=>'цельнолитые']]);normalizationCheck(count($conflict['warnings'])===1,'Explicit type disagreement held');
$solid=L::forProduct(array_replace($p,['name'=>'Шина цельнолитая']),[['attribute_id'=>61,'attribute_text'=>'цельнолитые'],['attribute_id'=>12,'attribute_text'=>'7']]);normalizationCheck(count($solid['unmapped'])>0,'Pressure not silently assigned to solid tyre');
normalizationCheck(L::sameUnitNumber('17.5 мм','in')==='17.5 мм','Different unit not stripped');normalizationCheck(L::sameUnitNumber('4 1/3','in')==='4 1/3','Non-terminating fraction never rounded');
$rejected=false;try{P::normalize(['type'=>'wheel_assembly','values'=>['tire_type'=>['state'=>'known','verification'=>'legacy_unverified','value'=>['solid']],'legacy_max_pressure_psi'=>['state'=>'known','verification'=>'legacy_unverified','value'=>'7']]]);}catch(InvalidArgumentException $e){$rejected=true;}normalizationCheck($rejected,'Pressure rejected for explicitly solid wheel');
echo "Literal legacy normalisation: separate source units, exact fractions, explicit name evidence, rim construction and conflicts OK\n";
